712: async function assertSafeRegularTarget(path: string): Promise<void> {
713:   try {
714:     const info = await lstat(path);
715:     if (info.isSymbolicLink() || !info.isFile()) {
716:       throw new Error(`Chat Gateway storage target is not a regular file: ${path}`);
717:     }
718:   } catch (error) {
719:     if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
