723: async function readBoundedRegularFile(
724:   path: string,
725:   maxBytes: number,
726:   label: string,
727: ): Promise<string> {
728:   const entry = await lstat(path);
729:   if (entry.isSymbolicLink() || !entry.isFile() || entry.size > maxBytes) {
730:     throw new Error(`${label} is not a bounded regular file`);
731:   }
732:   const handle = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
733:   try {
734:     const opened = await handle.stat();
735:     if (!opened.isFile() || opened.size > maxBytes) {
736:       throw new Error(`${label} is not a bounded regular file`);
737:     }
738:     return await handle.readFile("utf8");
739:   } finally {
740:     await handle.close();
741:   }
742: }
